import { useEffect } from 'react'
import { ConfirmationModalWrapper } from './index.style'
import { LANG_STRINGS } from '../../lang/index'

const ConfirmationModalV2 = ({
  visible, title, onOk, onCancel, okButtonColor,
  cancelButtonColor, okText, cancelText, okBtnId,
  hideCancel, className = '', ...props
}) => {
  useEffect(() => {
    if (visible) {
      document.body.style.overflow = 'hidden'
    }
    return () => { document.body.style.overflow = 'auto' }
  }, [visible])

  return visible ? (
    <ConfirmationModalWrapper
      okButtonColor={okButtonColor}
      cancelButtonColor={cancelButtonColor}
    >
      <div className={`modal-container ${className}`}>
        {
          title && (
            <div className='modal-title text-normal text-bold text-center text-capitalize text-dark'>
              {title}
            </div>
          )
        }
        <div className='modal-content'>
          {props.children}
        </div>
        <div className='modal-footer text-right'>
          {
            !hideCancel && (
              <button
                className='cancel-btn text-x-small text-uppercase text-extra-bold'
                onClick={onCancel}
              >
                {cancelText || LANG_STRINGS.no}
              </button>
            )
          }
          <button
            className='ok-btn text-x-small text-uppercase text-extra-bold'
            onClick={onOk}
            data-gtm-element-id={okBtnId}
          >
            {okText || LANG_STRINGS.remove}
          </button>
        </div>
      </div>
    </ConfirmationModalWrapper>
  ) : null
}
export default ConfirmationModalV2
