import { useState, useEffect, useMemo } from 'react'
import { useHistory } from 'react-router'
import { connect } from 'react-redux'
import { get } from 'lodash'
import moment from 'moment'
import Cookies from 'universal-cookie'
import { BottomActionContainerStyle, Grid, Row } from '../../../../../commonStyle/index.style'
import { Button, Container, CustomText } from '../../../../../components'
import ConfirmationModalV2 from '../../../../../components/ConfirmationModalV2'
import RadioInput from '../../../../../components/DynamicForm/components/RadioInput'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { TRANSACTIONS_TYPE } from '../../constants'
import { IS_TRANSACTION_CHANGE } from '../../../../../constants/cookies'
import { LANG_STRINGS } from '../../../../../lang'
import { INFORMATION_NEW } from '../../../../../images'
import policyActions from '../../../../../redux/policy/action'
import { TransactionChangeStyle } from './index.style'

const cookies = new Cookies()

function TransactionChange(props) {
  const {
    applicationDetail = {},
    getApplicationDetail,
    resetPolicyStore,
    updateTransactionType,
    loader,
    transactionTypeStatus,
  } = props

  const history = useHistory()
  const policyId = get(props, 'match.params.policyId', '')

  const [selectedType, setSelectedType] = useState('NORMAL')
  const [showModal, setShowModal] = useState(false)

  const simulated = get(applicationDetail, 'payment_period.simulated_ppw', null)
  const startDate = get(simulated, 'start_date', '')
  const totalDays = get(simulated, 'total_days', 30)

  const paylaterExampleData = useMemo(() => {
    if (!startDate) return null

    const exampleData = LANG_STRINGS.payLaterExample(
      totalDays,
      moment(startDate).format('D MMMM YYYY'),
      moment(startDate).add(2, 'days').format('D MMMM YYYY'),
      moment(startDate).add(2, 'days').add(totalDays, 'days').format('D MMMM YYYY'),
      moment(startDate).format('D MMMM YYYY'),
      moment(startDate).subtract(2, 'days').format('D MMMM YYYY'),
      moment(startDate).add(totalDays, 'days').format('D MMMM YYYY')
    )
    return exampleData?.items
  }, [startDate, totalDays])

  useEffect(() => {
    getApplicationDetail({ policyId, includeInsuranceDetail: true })
    return () => {
      // empty the transaction detail
      resetPolicyStore(['applicationDetail'])
    }
  }, [getApplicationDetail, resetPolicyStore, policyId])

  // policyId
  useEffect(() => {
    if (transactionTypeStatus === 'success') {
      // simple go back if status is updated
      history.push(`/transactions/${policyId}/details`)
      cookies.set(IS_TRANSACTION_CHANGE, 'true', { path: '/' })
    }
  }, [history, policyId, transactionTypeStatus])

  const handleSelected = (option) => {
    setSelectedType(option.code)
  }

  const handleConfirmationModal = () => {
    setShowModal(!showModal)
  }

  const handleApplyType = () => {
    // here call the api to apply the transaction type
    if (selectedType === 'PAYLATER') {
      updateTransactionType(policyId)
    }
    handleConfirmationModal()
  }

  return (
    <Container
      title={LANG_STRINGS.transactionType}
      loader={loader || !startDate}
      hideBottomTabs
      className="bg-white"
      onBackClick={() => history.push(`/transactions/${policyId}/details`)}
    >
      <TransactionChangeStyle>
        <Row align="start" className="pay-later-info">
          <div>
            <img src={INFORMATION_NEW} alt="" />
          </div>
          <CustomText size="0.9em" color={AgentColorPallette.regular} padLeft="8px">
            {LANG_STRINGS.normalToPayLaterChangesInfo}
          </CustomText>
        </Row>
        <RadioInput
          data={TRANSACTIONS_TYPE}
          title={LANG_STRINGS.selectTransactionType}
          name="transaction_type"
          onChange={handleSelected}
        />
        {selectedType === 'PAYLATER' && (
          <Grid gridColumn="32px 1fr 32px">
            <div className="pay-later-terms-box">
              <CustomText
                size="12px"
                color={AgentColorPallette.fontGrey}
                style={{ display: 'flex', flexDirection: 'column', gap: 8 }}
              >
                <div>
                  <b>{LANG_STRINGS.payLaterTerms}</b>
                </div>
                <div>
                  {LANG_STRINGS.payLaterTerm1(
                    get(applicationDetail, 'payment_period.simulated_ppw.total_days', 30)
                  )}
                </div>
                <div>
                  <b>{LANG_STRINGS.example}</b>
                </div>
                <ul style={{ margin: 0, paddingLeft: 18 }}>
                  {paylaterExampleData?.map((item, idx) => (
                    <li key={idx} style={{ marginBottom: 4 }}>
                      {item}
                    </li>
                  ))}
                </ul>
                <div>{LANG_STRINGS.payLaterTerm2}</div>
              </CustomText>
            </div>
          </Grid>
        )}
        <BottomActionContainerStyle className="transaction-btn-box">
          <Button
            variant="filled"
            onClick={handleConfirmationModal}
            disabled={selectedType === 'NORMAL'}
          >
            {LANG_STRINGS.apply}
          </Button>
        </BottomActionContainerStyle>
      </TransactionChangeStyle>
      {
        <ConfirmationModalV2
          visible={showModal}
          onCancel={handleConfirmationModal}
          okText={LANG_STRINGS.yes}
          cancelText={LANG_STRINGS.no}
          onOk={handleApplyType}
          cancelButtonColor={AgentColorPallette.vibrantRed}
        >
          <CustomText color={AgentColorPallette.blackGrey} size="0.9em">
            {LANG_STRINGS.areYouSureYouWantToChangeTransaction}
          </CustomText>
        </ConfirmationModalV2>
      }
    </Container>
  )
}

const { updateTransactionType } = policyActions

export default connect(
  (state) => ({
    applicationDetail: state.Policy.applicationDetail,
    transactionTypeStatus: state.Policy.transactionTypeStatus,
    loader: state.Loading.UPDATE_TRANSACTION_TYPE,
  }),
  {
    updateTransactionType,
    getApplicationDetail: policyActions.getApplicationDetail,
    resetPolicyStore: policyActions.resetPolicyStore,
  }
)(TransactionChange)
